css:
.p33-wrap { max-width: 56rem; margin-inline: auto; display: grid; gap: var(--s-4); }
.p33-top { display: grid; gap: var(--s-2); }
.p33-top:empty { display: none; }
.p33-bar { display: flex; flex-wrap: wrap; align-items: center; gap: var(--s-2); }
.p33-groups { display: grid; gap: var(--s-4); }
.p33-groups .group { gap: var(--s-2); }
.p33-list .rec__actions { flex-wrap: wrap; justify-content: flex-end; }
.p33-list .rec__actions .link-btn { margin-inline-start: var(--s-2); }
.p33-list .rec__title { display: inline-flex; align-items: center; min-height: var(--hit); }
.p33-ok { display: inline-grid; place-items: center; min-width: var(--hit); min-height: var(--hit); }
.p33-rtipw { grid-column: 1 / -1; }
.p33-rtip { display: flex; justify-content: flex-end; }
.p33-nolinks { padding: var(--s-1) 0; }
@media not all and (min-width: 48rem) and (min-height: 31.25rem) { .p33-wrap.is-scrolled .p33-bar, .p33-wrap.is-scrolled .p33-above { display: none; } }
.p33-dis .link-btn[aria-disabled="true"] { color: var(--c-disabled-text); text-decoration: none; cursor: not-allowed; }
.p33-err { --frame-w: var(--w2); }
.p33-errbox { display: grid; gap: var(--s-3); justify-items: start; width: min(100%, 32rem); }
.p33-errbox .banner { width: 100%; }
.p33-center { min-height: calc(100cqh - 2 * var(--s-3)); display: grid; align-content: center; justify-items: center; gap: var(--s-3); text-align: center; padding: var(--s-5) var(--s-3); }
.p33-center p { max-width: var(--measure); }
.p33-load { justify-content: center; }
.p33-msg { color: var(--ink); max-width: var(--measure); }
.p33-nocards { display: grid; justify-items: start; gap: var(--s-3); padding: var(--s-4) 0; }
.p33-tiprow { display: flex; }

.p33-dlg .dialog__body { gap: var(--s-3); }
.p33-form { display: grid; gap: var(--s-4); }
.p33-cards { display: grid; gap: 0; }
.p33-cards .check { min-height: var(--hit); }
.p33-cards .check input:disabled:checked + .check__box { background-color: var(--line); border-color: var(--line); }
.p33-cards .check__label { flex: 1; }
.p33-cards .p33-conn { margin-inline-start: auto; font-size: var(--fs-cap); line-height: var(--lh-cap); color: var(--muted); }
.p33-cards .check { width: 100%; }
.p33-grp-head { display: flex; justify-content: space-between; align-items: baseline; gap: var(--s-2); font-size: var(--fs-small); line-height: var(--lh-small); font-weight: var(--fw-semibold); }
.p33-area .textarea, .textarea.p33-name { min-height: var(--ctl-h); padding: var(--s-2) var(--s-3); resize: none; overflow-wrap: anywhere; field-sizing: content; }
.p33-url { text-overflow: ellipsis; white-space: nowrap; }
.input.p33-ro, .textarea.p33-ro { border-color: var(--rule); color: var(--muted); background: var(--white); }
.input.p33-focus, .textarea.p33-focus { border: var(--w2) solid var(--blue); padding-inline: calc(var(--s-3) - var(--w1)); }
.p33-dup { flex-wrap: wrap; }
.p33-dup .banner__text { flex: 1 1 10rem; }
.p33-errwrap { padding: 0 var(--s-4); }
.p33-tipslot { display: flex; justify-content: flex-end; padding: var(--s-2) var(--s-4) 0; }
.p33-hint { color: var(--muted); font-size: var(--fs-cap); line-height: var(--lh-cap); }
.p33-note { font-size: var(--fs-small); line-height: var(--lh-small); }
.p33-foot { }

.input.p33-word { font-variant-numeric: normal; }

.brand { min-height: var(--hit); }
.emo { width: 1.125em; height: 1.125em; flex: none; vertical-align: -0.2em; fill: none; stroke: currentColor; stroke-width: 1.5; stroke-linecap: round; stroke-linejoin: round; }
@media (min-width: 37.5rem) and (max-height: 31.1875rem) { .tab { padding-inline: var(--s-1); } .tabwrap > .tab { padding-inline: var(--s-1) 1.75rem; font-size: var(--fs-cap); } }
.btn .spinner, .banner .spinner { width: var(--icon-sm); height: var(--icon-sm); }
.dialog__head { align-items: center; }
.field__hint { font-size: var(--fs-cap); line-height: var(--lh-cap); color: var(--muted); }
